from dispatch.entity_type.models import EntityType
from dispatch.signal.redaction import MASK


def _entity_type(project, jpath):
    return EntityType(name="Sensitive", jpath=jpath, regular_expression=None, project=project)


def test_find_entities_never_extracts_masked_values(session, signal_instance, project):
    from dispatch.entity.service import find_entities

    signal_instance.raw = {
        "session_token": "ghp_real_secret",
        "events": [{"authorization": "Bearer one"}, {"authorization": "Bearer two"}],
        "user": {"name": "alice"},
    }

    # payload not yet masked by the signal flow: the sensitive value must still be skipped
    entities = find_entities(session, signal_instance, [_entity_type(project, "session_token")])
    assert entities == []

    entities = find_entities(
        session, signal_instance, [_entity_type(project, "events[*].authorization")]
    )
    assert entities == []

    # a masked value that the flow already wrote into the payload is skipped too
    signal_instance.raw = {"session_token": MASK}
    entities = find_entities(session, signal_instance, [_entity_type(project, "session_token")])
    assert entities == []

    # unrelated fields are still extracted
    signal_instance.raw = {"session_token": "ghp_real_secret", "user": {"name": "alice"}}
    entities = find_entities(session, signal_instance, [_entity_type(project, "user.name")])
    assert [str(e.value) for e in entities] == ["alice"]

